UPDATE `advisory_templates` SET `instructions_fil` = 'Asahan ang napakalakas na hangin sa loob ng 24 na oras. Manatili sa loob ng bahay, iwasan ang hindi kailangang paglalakbay, at lumayo sa puno at linya ng kuryente. Ang mga pamilya sa {AREAS} ay maghanda sa paglikas sa {CENTER}.' WHERE `name` = 'Typhoon - Signal No. 2' AND BINARY `instructions_fil` = BINARY 'ASAHAN ANG NAPAKALAKAS NA HANGIN SA LOOB NG 24 NA ORAS. MANATILI SA LOOB NG BAHAY, IWASAN ANG HINDI KAILANGANG PAGLALAKBAY, AT LUMAYO SA PUNO AT LINYA NG KURYENTE. ANG MGA PAMILYA SA {AREAS} AY MAGHANDA SA PAGLIKAS SA {CENTER}.';
