UPDATE `advisory_templates` SET `instructions_fil` = 'Maaaring bumaha sa mababang lugar, lalo na sa {AREAS}. Ilipat sa mataas ang mga gamit at dokumento, huwag lumusong o magmaneho sa baha, at maghanda sa paglikas sa {CENTER}.' WHERE `name` = 'Heavy rain - flood watch' AND BINARY `instructions_fil` = BINARY 'MAAARING BUMAHA SA MABABANG LUGAR, LALO NA SA {AREAS}. ILIPAT SA MATAAS ANG MGA GAMIT AT DOKUMENTO, HUWAG LUMUSONG O MAGMANEHO SA BAHA, AT MAGHANDA SA PAGLIKAS SA {CENTER}.';
